def frames(I,O,bg,objcol):
    H,W=len(I),len(I[0])
    # connected comps of non-bg in I
    seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and not seen[i][j]:
                c=I[i][j]; stack=[(i,j)]; cells=[]; seen[i][j]=True
                while stack:
                    yy,xx=stack.pop(); cells.append((yy,xx))
                    for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=yy+dy,xx+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and I[ny][nx]==c:
                            seen[ny][nx]=True; stack.append((ny,nx))
                ys=[a for a,b in cells]; xs=[b for a,b in cells]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                res.append((y0,y1,x0,x1))
    # now group frame cells: connected comps of O!=bg&O!=objcol in O
    fseen=[[False]*W for _ in range(H)]
    outs=[]
    for i in range(H):
        for j in range(W):
            if O[i][j]!=bg and O[i][j]!=objcol and not fseen[i][j]:
                cc=O[i][j]; stack=[(i,j)]; cells=[]; fseen[i][j]=True
                while stack:
                    yy,xx=stack.pop(); cells.append((yy,xx))
                    for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=yy+dy,xx+dx
                        if 0<=ny<H and 0<=nx<W and not fseen[ny][nx] and O[ny][nx]==cc:
                            fseen[ny][nx]=True; stack.append((ny,nx))
                ys=[a for a,b in cells]; xs=[b for a,b in cells]
                outs.append((cc,min(ys),min(xs),max(ys),max(xs)))
    return res,outs
