def solve_exp(I,O=None,mode='border'):
    H,W=len(I),len(I[0])
    bg=I[0][0]
    objs=comps(I,bg)
    if mode=='full':
        C=np.zeros((H,W),int)
        for c,y0,y1,x0,x1 in objs:
            y0-=1;y1+=1;x0-=1;x1+=1
            C[y0:y1+1,x0:x1+1]+=1
        P=np.where(C>=2,3,np.where(C==1,1,O))
        return P
    elif mode=='border':
        C=np.zeros((H,W),int)
        for c,y0,y1,x0,x1 in objs:
            Y0,Y1,X0,X1=y0-1,y1+1,x0-1,x1+1
            for y in range(Y0,Y1+1):
                for x in range(X0,X1+1):
                    if y in (Y0,Y1) or x in (X0,X1): C[y][x]+=1
        P=np.zeros((H,W),int)
        for y in range(H):
            for x in range(W):
                if C[y][x]>=2: P[y][x]=3
                elif C[y][x]==1: P[y][x]=1
        # original objects preserved
        for c,y0,y1,x0,x1 in objs:
            for y in range(y0,y1+1):
                for x in range(x0,x1+1): P[y][x]=c
        return P
    else:
        raise ValueError

